@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap');
:root{--ink:#17242a;--muted:#75848a;--paper:#f3f2ed;--line:#dce1dc;--teal:#285951;--mint:#b6d2c4;--rust:#b96c50;--night:#101a20;--cream:#ece8dc;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}*{box-sizing:border-box}body{margin:0;background:var(--night);color:var(--ink);font-family:var(--sans);font-size:14px}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #5b9988;outline-offset:3px}.hidden{display:none!important}.screen{min-height:100vh}.title-screen{display:grid;grid-template-columns:48% 52%;background:#ebe9df;overflow:hidden}.title-copy{padding:10vh 8vw 6vh 10vw;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;position:relative;z-index:2}.eyebrow{font:10px var(--mono);letter-spacing:.18em;color:#85918c;margin:0 0 16px}.title-copy h1{font:500 clamp(76px,10vw,148px)/.79 var(--serif);letter-spacing:-.065em;margin:10px 0 28px;color:#1b302e}.title-copy h1 em{color:#638a7c;font-weight:500}.intro{font:20px/1.6 var(--serif);max-width:380px;color:#556663;margin:0 0 34px}.primary,.secondary,.text-button{border:0;padding:14px 20px;transition:.2s}.primary{color:white;background:#2e5e54;font-weight:600;letter-spacing:.02em;min-width:190px;text-align:left}.primary span{float:right;margin-left:20px}.primary:hover{background:#234c44;transform:translateY(-1px)}.secondary{background:#e5e8e2;color:#43554f}.text-button{background:none;color:#526b61}.small-note{color:#828a84;font-size:11px;max-width:330px;line-height:1.55;margin-top:30px}.title-art{position:relative;background:linear-gradient(180deg,#839da0 0%,#aebcb1 44%,#5f7777 45%,#344b4c 100%);overflow:hidden}.title-art:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(235,233,223,.15),transparent 40%),linear-gradient(0deg,rgba(14,32,34,.5),transparent 55%)}.window{position:absolute;width:43%;height:59%;top:12%;left:30%;border:12px solid #263d