font-size:12px}.trans-choice input{accent-color:#39695d}.setup-actions{display:flex;justify-content:space-between;margin-top:22px}.game-screen{background:#e9e9e2;height:100vh;min-height:620px;display:flex;flex-direction:column}.topbar{height:58px;background:#f7f6f1;display:flex;align-items:center;justify-content:space-between;padding:0 28px;border-bottom:1px solid #dce0db;flex:none}.brand{font:500 12px var(--mono);letter-spacing:.18em;color:#26443e}.brand i{font-style:normal;color:#8da99c}.chapter-label{font:10px var(--mono);letter-spacing:.13em;color:#52665e}.divider{padding:0 10px;color:#b1bbb3}.top-actions{display:flex;gap:18px}.top-actions button,.quiet-button{background:none;border:0;color:#62726b;font-size:11px}.top-actions kbd{margin-left:5px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 284px;gap:0;max-width:1500px;margin:0 auto;width:100%;padding:23px 30px 20px;flex:1;min-height:0}.world-column{min-width:0;display:flex;flex-direction:column;padding-right:25px}.location-line{height:30px;display:flex;align-items:center;gap:9px;font:10px var(--mono);letter-spacing:.13em;color:#61736d}.location-dot{width:6px;height:6px;border-radius:50%;background:#668f7d}.location-line #weatherLabel{margin-left:auto;color:#9da9a0;font-size:9px}.viewport-wrap{position:relative;width:100%;aspect-ratio:16/9;max-height:calc(100vh - 255px);background:#283c3b;overflow:hidden;box-shadow:0 12px 35px #223a3324}.viewport-wrap canvas{width:100%;height:100%;display:block;image-rendering:pixelated}.view-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 48%,#11211c33 100%);pointer-events:none}.crosshair{position:absolute;left:50%;top:50%;width:10px;height:10px;transform:translate(-50%,-50%);opacity:.75}.crosshair i,.crosshair b{position:absolute;background:#fff}.crosshair i{width:1px;height:9px;top:0;left:4px}.crosshair b{height:1px;width:9px;left:0;top:4px}.interaction-hint{position:absolute;bottom:25px;left:50%;transform:translateX