ock;background:#6c9884;transition:width .5s}.meter i.energy{background:#c59b64;width:62%}.meter-block p,.memory-mini>p:last-child{font-size:10px;color:#9aa39c;margin:0;line-height:1.5}.side-divider{border-top:1px solid #d5dcd5;margin:15px 0}.objective-mini{padding:0 0 16px}.objective-mini .eyebrow,.memory-mini .eyebrow{font-size:9px;margin-bottom:8px}.objective-mini>p:last-child{font:15px/1.45 var(--serif);color:#4b6158;margin:0}.fragment-count{font:18px var(--mono);letter-spacing:7px;color:#79978a;margin-bottom:7px}.side-bottom{margin-top:auto;padding-top:12px}.support-button{width:100%;text-align:left;background:#e0e9df;color:#3d6252;border:0;padding:12px 13px;font-size:11px;font-weight:600}.support-button span{display:block;font-weight:400;color:#73847b;font-size:10px;margin-top:4px}.quiet-button{padding:12px 0}.mobile-controls{display:none}.modal{position:fixed;inset:0;background:#111b1bd1;z-index:10;display:grid;place-items:center;padding:20px;backdrop-filter:blur(4px)}.dialogue-card,.utility-card,.ending-card{background:#f5f4ee;width:min(560px,100%);padding:34px 40px;box-shadow:0 25px 90px #0005;max-height:90vh;overflow:auto}.dialogue-meta{display:flex;align-items:center;font:10px var(--mono);letter-spacing:.16em;color:#829188}.dialogue-card h2{font:500 34px/1.18 var(--serif);color:#29423b;margin:14px 0}.dialogue-card>p{font:15px/1.75 var(--serif);color:#5d6b64;white-space:pre-line}.scene-tag{display:inline-block;background:#e7e8d8;color:#7e7956;font:9px var(--mono);letter-spacing:.12em;padding:6px 8px;margin-top:16px}.choice-list{display:flex;flex-direction:column;gap:8px;margin-top:23px}.choice-list button{background:#e8ebe4;border:1px solid #dce2da;text-align:left;color:#435a50;padding:12px 14px;font-size:12px;line-height:1.4;transition:.15s}.choice-list button:hover{background:#dce7dc;border-color:#aec6b7;transform:translateX(2px)}.dialogue-footer{border-top:1px solid #dce1da;margin-top:22px;padding-top:13px;color:#9aa39d;font-size:10px}.utility-card{width:min(530px,100%)}.utility-head{display:flex;justify-content:space-between;align-items:flex-start}.utility-head h2{margin-bottom:20px}.journal-tabs{display:flex;gap:18px;border-bottom:1px solid #d8ded7}.journal-tabs button{background:none;border:0;padding:10px 0;color:#87948b;font-size:11px}.journal-tabs button.active{color:#31584c;border-bottom:2px solid #6f9c87}.journal-content{min-height:170px;padding:19px 0;color:#65736c;font:14px/1.7 var(--serif)}.journal-entry{border-left:2px solid #b8cdbd;padding:3px 0 4px 13px;margin:0 0 15px}.journal-entry small{display:block;font:9px var(--mono);letter-spacing:.1em;color:#95a39a;margin-bottom:4px}.map-card{width:min(620px,100%)}.map-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.map-place{padding:14px 10px;background:#e8ebe4;border:1px solid #d8dfd7;min-height:72px;color:#426054}.map-place strong{display:block;font:13px var(--serif)}.map-place span{display:block;font:9px var(--mono);color:#95a197;margin-top:6px}.map-place.locked{opacity:.42}.map-place.current{border-color:#83a893;background:#dce8dd}.map-tip{font-size:11px;color:#839087;line-height:1.6;margin:16px 0 0}.settings-content{color:#67766e;line-height:1.6;font-size:13px}.settings-content .check-row{padding:12px 0}.danger-button{display:block;margin-top:24px;padding:10px 12px;border:1px solid #d6ada0;background:#f5e8e1;color:#a35b48;font-size:11px}.settings-support{margin-top:12px}.support-content{color:#67766e;font-size:12px;line-height:1.6}.support-lead{font:17px/1.6 var(--serif);color:#506158}.grounding-prompt{display:flex;align-items:center;gap:12px;border-bottom:1px solid #e1e4dc;padding:4px 0}.grounding-prompt span{font:22px var(--serif);color:#77a08a}.grounding-prompt p{margin:7px 0}.support-box{background:#e9eee6;padding:14px;margin:17px 0;font-size:11px}.support-box p{margin:7px 0 0}.support-content>.primary{width:100%;text-align:center}.breathing-status{text-align:center;color:#648878;font:16px var(--serif);padding-top:12px;min-height:34px}.ending-card{text-align:center;width:min(550px,100%);padding:42px}.ending-card h2{font:500 39px var(--serif);color:#2e5548;margin:12px 0}.ending-card>p:not(.eyebrow){font:16px/1.75 var(--serif);color:#64736b}.ending-symbol{font-size:34px;color:#80a88f}.ending-details{border-top:1px solid #dce1da;border-bottom:1px solid #dce1da;padding:14px;margin:20px 0;color:#819087;font-size:11px;line-height:1.7}.ending-card .primary{display:block;margin:auto;text-align:center}.ending-card .text-button{margin-top:8px}.ending-card .eyebrow{margin-bottom:18px}
@media(max-width:900px){.game-layout{grid-template-columns:minmax(0,1fr) 230px;padding:15px}.world-column{padding-right:17px}.side-panel{padding-left:16px}.controls-line span:last-child{display:none}.game-screen{min-height:560px}.viewport-wrap{max-height:calc(100vh - 245px)}}
@media(max-width:650px){.title-screen{grid-template-columns:1fr;min-height:100vh}.title-copy{padding:13vh 10vw 7vh}.title-copy h1{font-size:90px}.title-art{position:absolute;inset:0 0 0 25%;opacity:.18}.title-copy{background:linear-gradient(90deg,#ebe9dff2 0%,#ebe9dfd9 75%,transparent)}.setup-screen{padding:0;background:#f3f2ed}.setup-panel{padding:30px 22px;box-shadow:none}.setup-panel h2{font-size:32px}.setup-grid{gap:12px}.trans-choice label{display:inline-block;margin:0 10px 8px 0}.topbar{height:50px;padding:0 13px}.chapter-label{font-size:8px}.top-actions{gap:8px}.top-actions button{font-size:10px}.top-actions kbd{display:none}.brand{font-size:10px}.game-screen{height:100dvh;min-height:0}.game-layout{display:flex;flex-direction:column;padding:8px 10px 10px;overflow:auto}.world-column{padding:0;flex:none}.location-line{height:25px;font-size:8px}.viewport-wrap{aspect-ratio:4/3;max-height:none}.controls-line{padding:8px 0;gap:6px;font-size:8px}.controls-line kbd{font-size:8px;padding:2px}.controls-line span:last-child{display:none}.world-footer{padding:9px 0}.world-footer strong{font-size:16px}.world-footer p{font-size:10px}.map-button{padding:8px;font-size:10px}.side-panel{border-left:0;border-top:1px solid #d6ddd6;padding:8px 0 0;display:grid;grid-template-columns:1fr 1fr;gap:0 13px;flex:none}.profile-card{grid-column:1/-1;padding-bottom:8px}.avatar{width:30px;height:30px}.meter-block{padding:8px 0 4px}.meter-block p{font-size:9px}.side-divider{display:none}.objective-mini{padding:8px 0}.objective-mini>p:last-child{font-size:13px}.memory-mini{padding:8px 0}.fragment-count{font-size:14px}.side-bottom{grid-column:1/-1;display:flex;gap:10px;align-items:center;padding-top:6px}.support-button{padding:8px 10px}.quiet-button{white-space:nowrap}.mobile-controls{position:absolute;display:flex;flex-direction:column;gap:0;left:12px;bottom:10px;opacity:.72}.mobile-controls div{display:flex}.mobile-controls button{width:38px;height:34px;border:1px solid #e0e9dc88;background:#172b2799;color:#fff;font-size:16px}.interaction-hint{bottom:20px;font-size:10px}.dialogue-card,.utility-card{padding:25px 22px}.dialogue-card h2{font-size:28px}.dialogue-card>p{font-size:14px}.map-grid{gap:5px}.map-place{padding:10px 7px}.map-place strong{font-size:11px}.ending-card{padding:30px 22px}.ending-card h2{font-size:32px}}

(()=>{'use strict';
const $=id=>document.getElementById(id), screens=['titleScreen','setupScreen','gameScreen'];
const locations={home:{name:'HOME · KITCHEN',weather:'LIGHT RAIN',sky:'#819493',wall:'#adbbad',floor:'#756f60',accent:'#d2c8a9',objects:[['window',-3,8],['table',0,5],['plant',3,7],['door',0,11]],links:[['Northside High','school','Northside High · 8 min walk']],},school:{name:'NORTHSIDE HIGH · MAIN HALL',weather:'GREY MORNING',sky:'#8c9996',wall:'#b7b9aa',floor:'#777b72',accent:'#c9b894',objects:[['lockers',-3,8],['bench',2,7],['poster',3,10],['door',0,12]],links:[['Corner Shop','shop','Moss Corner Shop · 4 min']],},shop:{name:'MOSS CORNER SHOP',weather:'STILL RAINING',sky:'#9baca4',wall:'#b9bca9',floor:'#786c58',accent:'#d9b675',objects:[['shelf',-3,7],['counter',1,5],['window',3,8],['door',0,12]],links:[['Northside High','school','Northside High · 4 min'],['Park','park','Willow Park · 6 min']]},park:{name:'WILLOW PARK',weather:'CLOUDS BREAKING',sky:'#a8b8a5',wall:'#849b85',floor:'#687b64',accent:'#a8ae7e',objects:[['tree',-3,7],['bench',1,5],['tree',3,10],['door',0,13]],links:[['Corner Shop','shop','Moss Corner Shop · 6 min'],['Library','library','Public Library · 5 min']]},library:{name:'NORTHSIDE PUBLIC LIBRARY',weather:'QUIET AFTERNOON',sky:'#a7aaa0',wall:'#b5b39f',floor:'#796f60',accent:'#ccb981',objects:[['shelf',-3,7],['desk',0,5],['window',3,9],['door',0,12]],links:[['Park','park','Willow Park · 5 min'],['Youth Centre','center','Open Door Youth Centre · 8 min']]},center:{name:'OPEN DOOR YOUTH CENTRE',weather:'WARM LIGHT',sky:'#b6b9a2',wall:'#b6ad98',floor:'#7c725f',accent:'#83a791',objects:[['window',-3,8],['sofa',0,5],['plant',3,7],['door',0,12]],links:[['Library','library','Public Library · 8 min'],['School','school','Northside High · 10 min']]}};
const story={};
function makeStory(){return {
'mom1':{speaker:'MOM · KITCHEN',title:'Before the bell',text:'Rain threads down the kitchen window. Mom is packing lunches without looking up. “You were up late again. You know, you make everything so difficult lately.” She says it like a fact, not an accusation. Somehow that makes it sting more.',choices:[['“I’m not trying to make things difficult.”',{steady:3,trust:1,note:'You tried to explain. The words came out smaller than you meant.'}],['“I just feel tired all the time.”',{steady:2,truth:1,note:'You let one small truth out. It did not fix the morning, but it was real.'}],['Take the lunch and go. Maybe later.',{energy:1,note:'You saved the conversation for another time.'}]],after:'mom1done'},
'photo':{speaker:'YOU · BACKPACK',title:'The photograph',text:'Behind your math notebook is a photograph you have never seen before. A child in a yellow raincoat stands outside a house with a blue door. The picture has no date. On the back, in handwriting you almost recognize: “For when you’re ready.” Your chest tightens—not quite fear, not quite anything you can name.',choices:[['Put it away gently. You can look later.',{steady:2,fragment:'blueDoor',note:'A photograph: a yellow raincoat, a blue door. You do not know the child.'}],['Look at the blue door a little longer.',{fragment:'blueDoor',truth:2,note:'The blue door brought a feeling you cannot place. You let yourself look anyway.'}],['Ask the school counselor if they can help.',{trust:2,truth:1,fragment:'blueDoor',note:'You decided not to carry the question by yourself.'}]],after:'photoDone'},
'bully':{speaker:'JAMIE · HALLWAY',title:'Between classes',text:'Jamie and two friends block the hall. “Hey, what are you supposed to be today?” Their laughter catches on the tile. The words land hard. A teacher is nearby, but looking the other way. You notice your hands have gone cold.',choices:[['“That wasn’t okay. Move.”',{steady:5,agency:2,note:'Your voice shook. It was still your voice.'}],['Walk to the office and tell Ms. Rivera.',{trust:3,steady:2,agency:1,note:'Ms. Rivera listened. She said she would check in after class.'}],['Keep walking. Find a quieter place.',{energy:2,steady:-1,note:'Getting through the hall was enough for now.'}],['Ask a friend to walk with you.',{trust:2,agency:1,note:'Sam fell into step beside you. You did not have to explain.'}]],after:'bullyDone'},
'counselor':{speaker:'MS. RIVERA · COUNSELOR',title:'A chair by the window',text:'Ms. Rivera leaves a little space between you. “You don’t need the right words. We can start with what the last few days have felt like.” On her desk is a small bowl of smooth stones. Outside, the clouds are thinning.',choices:[['“I feel low most days, and I don’t know why.”',{truth:4,trust:3,steady:2,note:'You told Ms. Rivera the low feeling has been there a while. She offered to help you find support.'}],['“I keep finding things from when I was little.”',{truth:3,trust:3,fragment:'yellowThread',note:'Ms. Rivera said a memory can come back in pieces, and you do not have to force it.'}],['“Can we just sit quietly for a minute?”',{steady:4,trust:1,note:'You sat in the quiet. That counted as a conversation.'}],['“I’m not ready to talk.”',{agency:2,steady:1,note:'Ms. Rivera respected your no. The door stays open.'}]],after:'counselorDone'},
'sam':{speaker:'SAM · LOCKER ROW',title:'Someone notices',text:'Sam, who sits near you in science, catches up. “You’ve been kind of far away lately. No pressure, but I can walk with you.” The offer is ordinary. That is part of why it feels safe.',choices:[['“Thanks. I’d like that.”',{trust:3,steady:3,note:'You and Sam walked the long way to class, talking about music.'}],['“Maybe. I’m not great company today.”',{trust:1,steady:1,note:'Sam said, “That’s okay. I’ll be around.”'}],['“Can I tell you something I don’t understand?”',{trust:3,truth:2,note:'Sam listened without trying to solve you.'}]],after:'samDone'},
'photo2':{speaker:'YOU · AFTER SCHOOL',title:'A name on the back',text:'At the library, the photograph catches the lamplight. Under the first message, almost rubbed away, there is another line: “Mira, age six.” Your name now is different. Or maybe it has always been. You do not have to decide what that means today.',choices:[['Keep the name in your journal.',{fragment:'mira',truth:3,note:'Mira, age six. You wrote the name down without deciding what it meant.'}],['Ask the librarian if they recognize the house.',{fragment:'mira',trust:1,truth:2,note:'The librarian recognized the blue door as a street in your old neighborhood.'}],['Put the photograph away; this is enough today.',{fragment:'mira',steady:3,note:'You set the photograph down. It will still be there later.'}]],after:'photo2Done'},
'parent2':{speaker:'DAD · FRONT DOOR',title:'An unfinished conversation',text:'Dad sees the photograph in your hand. “You’re bringing up old stuff again? We did our best. You were such a difficult kid.” His voice sounds tired. Your memory is still missing, but the feeling in your body is not. Somewhere in the house a pipe knocks twice.',choices:[['“I was six. I needed you to keep me safe.”',{truth:4,agency:2,steady:-2,note:'You said what you needed then. Dad looked away. The truth is yours even if he cannot hold it yet.'}],['“I don’t remember. I need help understanding.”',{truth:3,trust:1,steady:1,note:'Dad admitted there are parts he does not know how to talk about. It was not an apology, but a door cracked open.'}],['“I can’t do this conversation now.”',{agency:2,steady:2,note:'You left the conversation before it could swallow the whole evening.'}],['Ask Mom to sit with you both.',{trust:2,truth:2,note:'Mom sat down. Nobody had all the answers, but you were not alone in the room.'}]],after:'parent2Done'},
'friend3':{speaker:'SAM · PARK',title:'The shape of a memory',text:'The air smells like wet leaves. Sam lets you talk about Mira, the photograph, and the empty places in your childhood. The words come out in pieces. “I don’t know if I’m remembering or imagining it,” you say. “You don’t have to know today,” Sam answers.',choices:[['Tell Sam about the blue door and the fear.',{truth:3,trust:3,fragment:'rain',note:'You told Sam what you felt. No details came back, only a little more room to breathe.'}],['Ask Sam to talk about something ordinary.',{steady:3,trust:1,note:'You talked about an awful movie and a very good sandwich.'}],['Say you want to speak with Ms. Rivera again.',{trust:3,agency:1,note:'Sam offered to wait while you made an appointment.'}]],after:'friend3Done'},
'home3':{speaker:'MOM · LIVING ROOM',title:'Trying to listen',text:'Mom sits at the far end of the couch. “I thought you were just being difficult,” she says. “I didn’t realize you were hurting. I’m sorry I kept saying that.” She looks scared of saying the wrong thing. So do you.',choices:[['“Please don’t call me difficult anymore.”',{agency:3,trust:2,note:'Mom agreed to try. You both know trying is not the same as getting it right.'}],['“Can you help me talk to someone?”',{trust:4,steady:2,note:'Mom offered to call the clinic with you. You chose a first step.'}],['“I don’t know what I need. Just stay here?”',{trust:3,steady:3,note:'Mom stayed. There was no big answer, just the two of you and the quiet.'}],['Thank her, but keep some distance.',{agency:2,steady:1,note:'You accepted the apology without pretending everything was fixed.'}]],after:'home3Done'},
'final':{speaker:'YOU · A QUIET PLACE',title:'What you carry forward',text:'The week is ending. The photograph is still only a photograph. Your childhood has not returned as a neat story, and you do not owe anyone a complete explanation. But you have a few more names for what is happening now, and a few people who might listen.',choices:[['Write down what you want to remember.',{truth:2,agency:2,note:'You made a small plan, in your own words.'}],['Choose one person to ask for help.',{trust:3,agency:1,note:'You picked one person. A first step can be very small.'}],['Rest. You have done enough for today.',{steady:3,note:'You let the day be finished.'}]],after:'finish'}
};}
const state={};let sceneDefs=makeStory(),keys={},last=0,raf=0,breathTimer=0,activeTab='notes',toastTimer=0;
function fresh(){return {name:'Alex',gender:'nonbinary',sexuality:'skip',pronouns:'they',trans:'no',soft:false,location:'home',day:1,time:'BEFORE SCHOOL',x:0,z:0,yaw:0,steady:54,energy:62,truth:0,trust:0,agency:0,fragments:[],visited:{},flags:{},notes:[],unlocked:['home','school','shop','park','library','center'],ending:null};}
function showScreen(id){screens.forEach(s=>$(s).classList.toggle('hidden',s!==id))}
function modal(id,on=true){$(id).classList.toggle('hidden',!on)}
function save(){try{localStorage.setItem('quietHoursSave',JSON.stringify(state));toast('Progress saved on this device.')}catch(e){toast('Could not save in this browser.')}}
function loadSave(){try{return JSON.parse(localStorage.getItem('quietHoursSave')||'null')}catch(e){return null}}
function beginSetup(){showScreen('setupScreen')}
function startGame(newStory=true){if(newStory){Object.assign(state,fresh(),{name:$('playerName').value.trim().slice(0,18)||'Alex',gender:$('gender').value,sexuality:$('sexuality').value,pronouns:$('pronouns').value,trans:document.querySelector('input[name="trans"]:checked').value,soft:$('softMode').checked});}showScreen('gameScreen');updateUI();draw();}
function updateUI(){if(!state.location)state.location='home';const loc=locations[state.location];$('locationLabel').textContent=loc.name;$('weatherLabel').textContent=loc.weather;$('dayLabel').textContent='DAY '+state.day;$('timeLabel').textContent=state.time;$('profileName').textContent=state.name;$('avatarInitial').textContent=state.name.charAt(0).toUpperCase();$('steadyValue').textContent=state.steady;$('energyValue').textContent=state.energy;$('steadyBar').style.width=state.steady+'%';$('energyBar').style.width=state.energy+'%';$('fragmentCount').textContent=Array.from({length:6},(_,i)=>state.fragments.length>i?'●':'○').join(' ');$('objectiveTitle').textContent=state.flags['finish']?'A little more room':state.day===1?'A quiet morning':state.day===2?'A name in the margin':state.day===3?'The missing pieces':'A place to begin';$('objectiveText').textContent=objectiveText();$('threadText').textContent=state.day===1?'A strange photograph has appeared in your backpack.':state.day===2?'Someone knows the name written on the photograph.':state.day===3?'You do not have to remember everything at once.':'What kind of support might help next?';renderMap();}
function objectiveText(){if(state.day===1){if(!state.flags.mom1done)return'Check in with Mom, then head to school.';if(!state.flags.photoDone)return'Find the photograph in your backpack.';if(!state.flags.bullyDone)return'Get through the school day. Look for Sam or Ms. Rivera.';return'Explore Northside. Find somewhere that feels quiet.'}if(state.day===2){if(!state.flags.photo2Done)return'Look at the photograph somewhere quiet.';if(!state.flags.parent2Done)return'Go home and decide if you want to talk.';return'Find a safe place to spend the afternoon.'}if(state.day===3){if(!state.flags.friend3Done)return'Walk to the park. Sam is there after school.';if(!state.flags.home3Done)return'Go home. Mom wants to try again.';return'Find a quiet place, then choose what comes next.'}if(!state.flags.finish)return'Explore, talk, and decide what kind of support feels possible.';return'The week is yours. You can explore or begin again.'}
function changeMeter(key,n){state[key]=Math.max(0,Math.min(100,(state[key]||0)+n))}
function applyChoice(c){for(const k of ['steady','energy','trust','truth','agency'])if(c[k]){if(k==='steady'||k==='energy')changeMeter(k,c[k]);else state[k]=Math.max(0,(state[k]||0)+c[k]);}if(c.fragment&&!state.fragments.includes(c.fragment))state.fragments.push(c.fragment);if(c.note)state.notes.unshift({day:state.day,text:c.note});}
function chooseScene(id){const s=sceneDefs[id];if(!s)return;modal('dialogueModal');$('speakerLabel').textContent=s.speaker;$('dialogueTitle').textContent=s.title;$('dialogueText').textContent=state.soft?s.text.replace(/self-harm|dysphoria/gi,'difficult feelings'):s.text;$('sceneTag').classList.toggle('hidden',!s.fragment);$('choiceList').innerHTML='';s.choices.forEach(([label,effect])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{applyChoice(effect);if(s.after==='finish'){state.flags.finish=true;modal('dialogueModal',false);updateUI();endGame();return}if(s.after)state.flags[s.after]=true;modal('dialogueModal',false);updateUI();save();};$('choiceList').appendChild(b)});}
function endGame(){const fragments=state.fragments.length,trust=state.trust,truth=state.truth,agency=state.agency;let title,text,symbol;if(trust>=7&&state.steady>=35){title='A little more room';text='You have not solved the past, or made every hard day disappear. But you have someone to sit with you, a way to ask for help, and permission to go slowly. That is not a small ending. It is a beginning with room in it.';symbol='✳';}else if(truth>=7&&agency>=5){title='The words are yours';text='The memories are still incomplete. You have chosen your own words, your own pace, and a boundary you can keep. The people around you may need time to understand. You do not need their perfect understanding to begin caring for yourself.';symbol='◌';}else if(state.steady<24){title='A difficult week';text='By Friday, everything still feels heavy. You do not have to turn that into a lesson. Even here, you are not a failure. The story leaves you at a doorway: a school counselor, a trusted adult, or a helpline can be a next step when you are ready.';symbol='☾';}else{title='One step, then another';text='There are still questions, and not everyone knew how to listen. But the week did not erase you. You can keep exploring, return to a conversation, or ask one safe person to stay nearby. Nothing has to be decided all at once.';symbol='↗';}$('endingTitle').textContent=title;$('endingText').textContent=text;$('endingSymbol').textContent=symbol;$('endingDetails').textContent=`${fragments} memory fragments found · ${state.notes.length} moments journaled · Your identity and the ending are yours.`;modal('endingModal');state.ending=title;save();}

function draw(){const canvas=$('world'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,loc=locations[state.location]||locations.home;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h*.66);sky.addColorStop(0,loc.sky);sky.addColorStop(1,'#c1c4b2');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h*.66);ctx.fillStyle=loc.wall;ctx.fillRect(0,h*.3,w,h*.46);ctx.fillStyle=loc.floor;ctx.beginPath();ctx.moveTo(0,h*.69);ctx.lineTo(w,h*.69);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.strokeStyle='#e3d8bd35';ctx.lineWidth=2;for(let i=-5;i<=5;i++){ctx.beginPath();ctx.moveTo(w/2+i*14,h*.69);ctx.lineTo(w/2+i*85,h);ctx.stroke()}for(let j=1;j<5;j++){const y=h*.69+((h*.31)*(j*j/25));ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
// place architecture, viewed in perspective
ctx.fillStyle='#45524d';ctx.fillRect(0,h*.29,w,12);ctx.fillStyle=loc.accent;ctx.fillRect(0,h*.3,w,6);const objects=loc.objects||[];objects.forEach((o,i)=>{const [type,x,z]=o;const sx=w/2+(x-state.x)*100/(z*.42+1)-state.yaw*1.1,scale=1/(z*.13+0.35),oy=h*.69+(state.z-z)*2;drawObject(ctx,type,sx,oy,scale,loc,i)});
// rain atmosphere
if(state.location==='home'||state.location==='school'||state.location==='shop'){ctx.strokeStyle='#e5eee844';ctx.lineWidth=1;for(let i=0;i<60;i++){let x=(i*137+(Date.now()/28))%w,y=(i*91+(Date.now()/16))%h*.72;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+11);ctx.stroke()}}
// distant cinematic light and grain
const vignette=ctx.createRadialGradient(w/2,h*.45,h*.1,w/2,h*.5,h*.75);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#14231e30');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);ctx.fillStyle='#e7e7d20a';for(let i=0;i<120;i++){ctx.fillRect((i*73+Math.floor(Date.now()/80))%w,(i*97)%h,2,2)}
const near=nearest();const hint=$('interactionHint');hint.classList.toggle('hidden',!near);if(near)hint.querySelector('span').textContent=near.label;}
function drawObject(ctx,type,x,y,s,loc,i){const h=ctx.canvas.height,w=ctx.canvas.width;ctx.save();ctx.translate(x,y);ctx.scale(s,s);if(type==='window'){ctx.fillStyle='#30433e';ctx.fillRect(-45,-170,90,170);ctx.fillStyle=loc.sky;ctx.fillRect(-37,-162,74,154);ctx.fillStyle='#d5cfad';ctx.fillRect(-3,-162,6,154);ctx.fillRect(-37,-82,74,5);ctx.fillStyle='#f0d7a866';ctx.beginPath();ctx.arc(-14,-126,14,0,Math.PI*2);ctx.fill()}else if(type==='door'){ctx.fillStyle='#46594e';ctx.fillRect(-40,-140,80,140);ctx.fillStyle='#738b76';ctx.fillRect(-33,-132,66,132);ctx.fillStyle='#d4b77a';ctx.beginPath();ctx.arc(20,-68,4,0,Math.PI*2);ctx.fill()}else if(type==='table'||type==='desk'||type==='counter'){ctx.fillStyle='#665646';ctx.fillRect(-85,-46,170,17);ctx.fillStyle='#564b3e';ctx.fillRect(-70,-29,12,65);ctx.fillRect(58,-29,12,65);ctx.fillStyle='#ded1aa';ctx.fillRect(-25,-60,48,13);if(type==='desk')ctx.fillStyle='#7d6953';ctx.fillRect(12,-63,12,17)}else if(type==='plant'||type==='tree'){const t=type==='tree'?1.5:1;ctx.fillStyle='#475c4a';ctx.fillRect(-5,-52*t,10,52*t);ctx.fillStyle=i%2?'#627c5d':'#73896a';for(let a=0;a<5;a++){ctx.beginPath();ctx.arc((a-2)*15,-75*t-(a%2)*12,22*t,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#765b45';ctx.fillRect(-20,0,40,12)}else if(type==='bench'){ctx.fillStyle='#6e6857';ctx.fillRect(-70,-45,140,12);ctx.fillRect(-65,-64,130,9);ctx.fillRect(-55,-33,9,38);ctx.fillRect(47,-33,9,38)}else if(type==='shelf'||type==='lockers'){ctx.fillStyle=type==='shelf'?'#625b49':'#526565';ctx.fillRect(-75,-160,150,160);for(let n=0;n<4;n++){ctx.fillStyle=type==='shelf'?'#a4936d':'#748783';ctx.fillRect(-70,-145+n*38,140,4);for(let j=0;j<4;j++){ctx.fillStyle=['#7b8166','#bc9568','#7d8981','#a97964'][(j+n)%4];ctx.fillRect(-61+j*33,-177+n*38,24,31)}}}else if(type==='poster'){ctx.fillStyle='#eee8d4';ctx.fillRect(-47,-92,94,92);ctx.fillStyle='#789885';ctx.fillRect(-35,-78,70,42);ctx.fillStyle='#b17b62';ctx.fillRect(-32,-22,64,5);ctx.fillRect(-22,-11,44,4)}else if(type==='sofa'){ctx.fillStyle='#657f70';ctx.fillRect(-80,-64,160,63);ctx.fillRect(-93,-52,18,53);ctx.fillRect(75,-52,18,53);ctx.fillStyle='#b0b99a';ctx.fillRect(-55,-53,48,24);ctx.fillRect(10,-53,48,24)}else{ctx.fillStyle='#716e5f';ctx.fillRect(-40,-100,80,100)}ctx.restore()}
function nearest(){// Each scene trigger is an approachable point in the current room.
let options=[];const add=(label,fn,x=0,z=5)=>options.push({label,fn,x,z});const f=state.flags,loc=state.location;
if(loc==='home'){if(state.day===1&&!f.mom1done)add('Talk with Mom',()=>chooseScene('mom1'),0,5);if(state.day===1&&f.mom1done&&!f.photoDone)add('Look in your backpack',()=>chooseScene('photo'),-2,4);if(state.day===2&&f.photo2Done&&!f.parent2Done)add('Talk with Dad',()=>chooseScene('parent2'),0,5);if(state.day===3&&f.friend3Done&&!f.home3Done)add('Talk with Mom',()=>chooseScene('home3'),0,5);}
if(loc==='school'&&state.day===1){if(f.photoDone&&!f.bullyDone)add('Get through the hallway',()=>chooseScene('bully'),0,5);else if(f.bullyDone&&!f.counselorDone)add('Visit Ms. Rivera',()=>chooseScene('counselor'),-2,5);else if(f.counselorDone&&!f.samDone)add('Talk with Sam',()=>chooseScene('sam'),2,5);}
if(loc==='library'&&state.day===2&&!f.photo2Done)add('Read the photograph',()=>chooseScene('photo2'),0,5);
if(loc==='park'&&state.day===3&&!f.friend3Done)add('Meet Sam',()=>chooseScene('friend3'),0,5);
if(state.day===1&&state.location==='shop'&&f.bullyDone&&!f.counselorDone)add('Ask for directions',()=>{toast('A shopkeeper points out the school counselor’s office.');},0,5);
if(state.day>=3&&state.flags.home3Done&&!f.finish&&['park','library','center'].includes(loc))add('Find a quiet place',()=>chooseScene('final'),0,5);
const door=locations[loc].links;door.forEach(([label,target,info],i)=>{if(state.unlocked.includes(target))add('Go to '+label,()=>travel(target,info),i===0?2:-2,11)});let closest=null,dist=2.1;options.forEach(o=>{const d=Math.hypot((o.x-state.x),(o.z-state.z));if(d<dist){dist=d;closest=o}});return closest;}
function travel(target,info){if(!state.unlocked.includes(target))return;state.location=target;state.x=0;state.z=0;state.energy=Math.max(0,state.energy-2);if(target==='school'&&state.day===1)state.time='MORNING';if(target==='park'&&state.day>=1)state.time='AFTERNOON';if(target==='library')state.time='AFTERNOON';if(target==='home'&&state.day===1&&state.flags.samDone){advanceDay();return}if(target==='home'&&state.day===2&&state.flags.parent2Done){advanceDay();return}toast(info);updateUI();draw();save();}
function advanceDay(){if(state.day===1){state.day=2;state.time='TUESDAY · AFTER SCHOOL';state.location='home';state.energy=Math.max(25,state.energy-11);state.steady=Math.max(10,state.steady-4);state.flags.bullyDone=true;toast('TUESDAY · A new note is tucked into the photograph.')}else if(state.day===2){state.day=3;state.time='WEDNESDAY · AFTER SCHOOL';state.location='park';state.energy=Math.max(18,state.energy-8);toast('WEDNESDAY · Sam said they would be at the park.')}else if(state.day===3){state.day=4;state.time='FRIDAY · LATE AFTERNOON';state.location='center';state.energy=Math.max(15,state.energy-6);toast('FRIDAY · The youth centre is open late today.')}else{state.location='center';state.time='EVENING';}updateUI();draw();save();}
function renderMap(){const box=$('mapGrid');box.innerHTML='';const places=[['home','Home'],['school','Northside High'],['shop','Corner shop'],['park','Willow Park'],['library','Public library'],['center','Youth centre']];places.forEach(([id,label])=>{const b=document.createElement('div');b.className='map-place'+(state.location===id?' current':'')+(!state.unlocked.includes(id)?' locked':'');b.innerHTML=`<strong>${label}</strong><span>${id===state.location?'YOU ARE HERE':state.unlocked.includes(id)?'OPEN TO EXPLORE':'NOT YET OPEN'}</span>`;box.appendChild(b)})}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),2500)}
function interact(){const n=nearest();if(n)n.fn()}
function move(dt){const speed=dt*.008;let dx=0,dz=0;if(keys.KeyW||keys.ArrowUp)dz+=speed;if(keys.KeyS||keys.ArrowDown)dz-=speed;if(keys.KeyA)dx-=speed;if(keys.KeyD)dx+=speed;if(keys.ArrowLeft)state.yaw=Math.max(-120,Math.min(120,state.yaw-1.6));if(keys.ArrowRight)state.yaw=Math.max(-120,Math.min(120,state.yaw+1.6));state.x=Math.max(-3.3,Math.min(3.3,state.x+dx));state.z=Math.max(-1,Math.min(10,state.z+dz));}
function frame(t){if(!raf)return;const dt=Math.min(40,t-last||16);last=t;move(dt);draw();raf=requestAnimationFrame(frame)}
function startLoop(){if(raf)cancelAnimationFrame(raf);raf=1;last=0;frame(0)}
function stopLoop(){cancelAnimationFrame(raf);raf=0}
function journal(tab=activeTab){activeTab=tab;document.querySelectorAll('.journal-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const content=$('journalContent');if(tab==='notes'){content.innerHTML=state.notes.length?state.notes.map(n=>`<div class="journal-entry"><small>DAY ${n.day}</small>${escapeHtml(n.text)}</div>`).join(''):'<p>Nothing written yet. Your moments will appear here as you go.</p>'}else if(tab==='memories'){const labels={blueDoor:'A yellow raincoat and a blue door',yellowThread:'The color of a thread from a childhood sweater',mira:'A name on the back of a photograph',rain:'The feeling of rain and a familiar doorstep'};content.innerHTML=state.fragments.length?state.fragments.map(f=>`<div class="journal-entry"><small>FRAGMENT · NOT A COMPLETE MEMORY</small>${escapeHtml(labels[f]||'A feeling that has not found its words yet.')}</div>`).join(''):'<p>No fragments found yet. You never have to search for them.</p>'}else{content.innerHTML='<div class="journal-entry"><small>HOME</small>Mom and Dad care about you, but do not always understand what you are going through.</div><div class="journal-entry"><small>SCHOOL</small>Ms. Rivera is a counselor. Sam offered to walk with you.</div><div class="journal-entry"><small>YOU</small>Your identity is yours to define, change, or leave unanswered.</div>'}modal('journalModal')}
function escapeHtml(str){return String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function closeAll(){document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'))}
function setup(){stateSoftListeners();$('beginBtn').onclick=beginSetup;$('continueBtn').onclick=()=>{const saved=loadSave();if(saved){Object.assign(state,fresh(),saved);startGame(false);}};$('backBtn').onclick=()=>showScreen('titleScreen');$('startGameBtn').onclick=()=>{startGame(true);save();chooseScene('mom1')};$('journalBtn').onclick=()=>journal();$('pauseBtn').onclick=()=>modal('settingsModal');$('settingsBtn').onclick=()=>modal('settingsModal');$('supportBtn').onclick=()=>modal('supportModal');$('settingsSupport').onclick=()=>{modal('settingsModal',false);modal('supportModal')};$('mapBtn').onclick=()=>modal('mapModal');$('saveBtn').onclick=save;$('resetBtn').onclick=()=>{if(confirm('Erase your saved story and return to the beginning?')){localStorage.removeItem('quietHoursSave');location.reload()}};$('restartEnding').onclick=()=>{localStorage.removeItem('quietHoursSave');location.reload()};$('endingClose').onclick=()=>modal('endingModal',false);$('breathingBtn').onclick=breathing;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal(b.dataset.close,false));document.querySelectorAll('.journal-tabs button').forEach(b=>b.onclick=()=>journal(b.dataset.tab));$('softModeLive').onchange=e=>{state.soft=e.target.checked;$('softMode').checked=state.soft;save()};$('softMode').onchange=e=>{state.soft=e.target.checked};document.querySelectorAll('.mobile-controls button').forEach(b=>{const dir=b.dataset.move;const map={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'};b.onpointerdown=e=>{e.preventDefault();keys[map[dir]]=true};b.onpointerup=b.onpointerleave=()=>keys[map[dir]]=false});document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){const opened=[...document.querySelectorAll('.modal')].find(m=>!m.classList.contains('hidden'));if(opened)opened.classList.add('hidden');else modal('settingsModal');return}if(e.key.toLowerCase()==='e'){interact();return}if(e.key.toLowerCase()==='j'){journal();return}keys[e.code]=true});document.addEventListener('keyup',e=>{keys[e.code]=false});document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m&&m.id!=='endingModal')m.classList.add('hidden')}));}
function stateSoftListeners(){const saved=loadSave();if(saved){$('continueBtn').classList.remove('hidden');}}
function breathing(){const out=$('breathingStatus'),btn=$('breathingBtn');btn.disabled=true;let n=0;const words=['Breathe in gently…','Pause, if that feels okay…','Let the breath go…'];function tick(){if(n>=6){out.textContent='You can return whenever you feel ready.';btn.disabled=false;return}out.textContent=words[n%3];n++;breathTimer=setTimeout(tick,5000)}tick()}
