(()=>{'use strict';
const $=id=>document.getElementById(id),screens=['titleScreen','setupScreen','gameScreen'];
const places={home:{name:'HOME · KITCHEN',weather:'LIGHT RAIN',sky:'#819493',wall:'#adbbad',floor:'#756f60',accent:'#d2c8a9',objects:[['window',-3,8],['table',0,5],['plant',3,7]],links:[['Northside High','school'],['Corner Shop','shop']]},school:{name:'NORTHSIDE HIGH · MAIN HALL',weather:'GREY MORNING',sky:'#8c9996',wall:'#b7b9aa',floor:'#777b72',accent:'#c9b894',objects:[['lockers',-3,8],['bench',2,7],['poster',3,10]],links:[['Home','home'],['Corner Shop','shop']]},shop:{name:'MOSS CORNER SHOP',weather:'STILL RAINING',sky:'#9baca4',wall:'#b9bca9',floor:'#786c58',accent:'#d9b675',objects:[['shelf',-3,7],['counter',1,5],['window',3,8]],links:[['Northside High','school'],['Willow Park','park'],['Home','home']]},park:{name:'WILLOW PARK',weather:'CLOUDS BREAKING',sky:'#a8b8a5',wall:'#849b85',floor:'#687b64',accent:'#a8ae7e',objects:[['tree',-3,7],['bench',1,5],['tree',3,10]],links:[['Corner Shop','shop'],['Public Library','library']]},library:{name:'NORTHSIDE PUBLIC LIBRARY',weather:'QUIET AFTERNOON',sky:'#a7aaa0',wall:'#b5b39f',floor:'#796f60',accent:'#ccb981',objects:[['shelf',-3,7],['desk',0,5],['window',3,9]],links:[['Willow Park','park'],['Youth Centre','center']]},center:{name:'OPEN DOOR YOUTH CENTRE',weather:'WARM LIGHT',sky:'#b6b9a2',wall:'#b6ad98',floor:'#7c725f',accent:'#83a791',objects:[['window',-3,8],['sofa',0,5],['plant',3,7]],links:[['Public Library','library'],['Northside High','school']]}};
const scenes={mom1:{speaker:'MOM · KITCHEN',title:'Before the bell',text:'Rain threads down the kitchen window. Mom is packing lunches without looking up. “You were up late again. You know, you make everything so difficult lately.” She says it like a fact, not an accusation. Somehow that makes it sting more.',choices:[['“I’m not trying to make things difficult.”',{steady:3,trust:1,note:'You tried to explain. The words came out smaller than you meant.'}],['“I just feel tired all the time.”',{steady:2,truth:1,note:'You let one small truth out. It did not fix the morning, but it was real.'}],['Take the lunch and go. Maybe later.',{energy:1,note:'You saved the conversation for another time.'}]],after:'mom1done'},photo:{speaker:'YOU · BACKPACK',title:'The photograph',text:'Behind your math notebook is a photograph you have never seen before. A child in a yellow raincoat stands outside a house with a blue door. The picture has no date. On the back, in handwriting you almost recognize: “For when you’re ready.” Your chest tightens—not quite fear, not quite anything you can name.',choices:[['Put it away gently. You can look later.',{steady:2,fragment:'blueDoor',note:'A photograph: a yellow raincoat, a blue door. You do not know the child.'}],['Look at the blue door a little longer.',{fragment:'blueDoor',truth:2,note:'The blue door brought a feeling you cannot place.'}],['Ask the school counselor if they can help.',{trust:2,truth:1,fragment:'blueDoor',note:'You decided not to carry the question by yourself.'}]],after:'photoDone'},bully:{speaker:'JAMIE · HALLWAY',title:'Between classes',text:'Jamie and two friends block the hall. “Hey, what are you supposed to be today?” Their laughter catches on the tile. The words land hard. A teacher is nearby, but looking the other way. You notice your hands have gone cold.',choices:[['“That wasn’t okay. Move.”',{steady:5,agency:2,note:'Your voice shook. It was still your voice.'}],['Walk to the office and tell Ms. Rivera.',{trust:3,steady:2,agency:1,note:'Ms. Rivera listened. She said she would check in after class.'}],['Keep walking. Find a quieter place.',{energy:2,steady:-1,note:'Getting through the hall was enough for now.'}],['Ask a friend to walk with you.',{trust:2,agency:1,note:'Sam fell into step beside you.'}]],after:'bullyDone'},counselor:{speaker:'MS. RIVERA · COUNSELOR',title:'A chair by the window',text:'Ms. Rivera leaves a little space between you. “You don’t need the right words. We can start with what the last few days have felt like.” On her desk is a small bowl of smooth stones. Outside, the clouds are thinning.',choices:[['“I feel low most days, and I don’t know why.”',{truth:4,trust:3,steady:2,note:'You told Ms. Rivera the low feeling has been there a while.'}],['“I keep finding things from when I was little.”',{truth:3,trust:3,fragment:'yellowThread',note:'Ms. Rivera said a memory can come back in pieces.'}],['“Can we just sit quietly for a minute?”',{steady:4,trust:1,note:'You sat in the quiet. That counted as a conversation.'}],['“I’m not ready to talk.”',{agency:2,steady:1,note:'Ms. Rivera respected your no. The door stays open.'}]],after:'counselorDone'},sam:{speaker:'SAM · LOCKER ROW',title:'Someone notices',text:'Sam, who sits near you in science, catches up. “You’ve been kind of far away lately. No pressure, but I can walk with you.” The offer is ordinary. That is part of why it feels safe.',choices:[['“Thanks. I’d like that.”',{trust:3,steady:3,note:'You and Sam walked the long way to class, talking about music.'}],['“Maybe. I’m not great company today.”',{trust:1,steady:1,note:'Sam said, “That’s okay. I’ll be around.”'}],['“Can I tell you something I don’t understand?”',{trust:3,truth:2,note:'Sam listened without trying to solve you.'}]],after:'samDone'},photo2:{speaker:'YOU · AFTER SCHOOL',title:'A name on the back',text:'At the library, the photograph catches the lamplight. Under the first message, almost rubbed away, there is another line: “Mira, age six.” Your name now is different. Or maybe it has always been. You do not have to decide what that means today.',choices:[['Keep the name in your journal.',{fragment:'mira',truth:3,note:'Mira, age six. You wrote the name down without deciding what it meant.'}],['Ask the librarian if they recognize the house.',{fragment:'mira',trust:1,truth:2,note:'The librarian recognized the blue door as a street in your old neighborhood.'}],['Put the photograph away; this is enough today.',{fragment:'mira',steady:3,note:'You set the photograph down. It will still be there later.'}]],after:'photo2Done'},parent2:{speaker:'DAD · FRONT DOOR',title:'An unfinished conversation',text:'Dad sees the photograph in your hand. “You’re bringing up old stuff again? We did our best. You were such a difficult kid.” Your memory is still missing, but the feeling in your body is not. Somewhere in the house a pipe knocks twice.',choices:[['“I was six. I needed you to keep me safe.”',{truth:4,agency:2,steady:-2,note:'You said what you needed then. The truth is yours even if he cannot hold it yet.'}],['“I don’t remember. I need help understanding.”',{truth:3,trust:1,steady:1,note:'Dad admitted there are parts he does not know how to talk about.'}],['“I can’t do this conversation now.”',{agency:2,steady:2,note:'You left the conversation before it could swallow the whole evening.'}],['Ask Mom to sit with you both.',{trust:2,truth:2,note:'Mom sat down. Nobody had all the answers.'}]],after:'parent2Done'},friend3:{speaker:'SAM · PARK',title:'The shape of a memory',text:'The air smells like wet leaves. Sam lets you talk about Mira, the photograph, and the empty places in your childhood. The words come out in pieces. “I don’t know if I’m remembering or imagining it,” you say. “You don’t have to know today,” Sam answers.',choices:[['Tell Sam about the blue door and the fear.',{truth:3,trust:3,fragment:'rain',note:'You told Sam what you felt. No details came back, only a little more room to breathe.'}],['Ask Sam to talk about something ordinary.',{steady:3,trust:1,note:'You talked about an awful movie and a very good sandwich.'}],['Say you want to speak with Ms. Rivera again.',{trust:3,agency:1,note:'Sam offered to wait while you made an appointment.'}]],after:'friend3Done'},home3:{speaker:'MOM · LIVING ROOM',title:'Trying to listen',text:'Mom sits at the far end of the couch. “I thought you were just being difficult,” she says. “I didn’t realize you were hurting. I’m sorry I kept saying that.” She looks scared of saying the wrong thing. So do you.',choices:[['“Please don’t call me difficult anymore.”',{agency:3,trust:2,note:'Mom agreed to try. Trying is not the same as getting it right.'}],['“Can you help me talk to someone?”',{trust:4,steady:2,note:'Mom offered to call the clinic with you. You chose a first step.'}],['“I don’t know what I need. Just stay here?”',{trust:3,steady:3,note:'Mom stayed. There was no big answer, just the two of you.'}],['Thank her, but keep some distance.',{agency:2,steady:1,note:'You accepted the apology without pretending everything was fixed.'}]],after:'home3Done'},final:{speaker:'YOU · A QUIET PLACE',title:'What you carry forward',text:'The week is ending. The photograph is still only a photograph. Your childhood has not returned as a neat story, and you do not owe anyone a complete explanation. But you have a few more names for what is happening now, and a few people who might listen.',choices:[['Write down what you want to remember.',{truth:2,agency:2,note:'You made a small plan, in your own words.'}],['Choose one person to ask for help.',{trust:3,agency:1,note:'You picked one person. A first step can be very small.'}],['Rest. You have done enough for today.',{steady:3,note:'You let the day be finished.'}]],after:'finish'}};
const state={};let keys={},raf=0,last=0,toastTimer=0,activeTab='notes';
function fresh(){return{name:'Alex',gender:'nonbinary',sexuality:'skip',pronouns:'they',trans:'no',soft:false,location:'home',day:1,time:'BEFORE SCHOOL',x:0,z:0,yaw:0,steady:54,energy:62,truth:0,trust:0,agency:0,fragments:[],flags:{},notes:[],ending:null}}
function show(id){screens.forEach(x=>$(x).classList.toggle('hidden',x!==id))}function modal(id,on=true){$(id).classList.toggle('hidden',!on)}
function toast(t){const e=$('toast');e.textContent=t;e.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.add('hidden'),2400)}
function save(){try{localStorage.setItem('quietHoursSave',JSON.stringify(state));toast('Progress saved on this device.')}catch(e){toast('Could not save in this browser.')}}
function load(){try{return JSON.parse(localStorage.getItem('quietHoursSave')||'null')}catch(e){return null}}
function start(newGame){if(newGame)Object.assign(state,fresh(),{name:$('playerName').value.trim().slice(0,18)||'Alex',gender:$('gender').value,sexuality:$('sexuality').value,pronouns:$('pronouns').value,trans:document.querySelector('[name=trans]:checked').value,soft:$('softMode').checked});show('gameScreen');update();draw()}

function objective(){let f=state.flags;if(state.day===1)return!f.mom1done?'Check in with Mom, then head to school.':!f.photoDone?'Find the photograph in your backpack.':!f.bullyDone?'Get through the school day. Look for Sam or Ms. Rivera.':'Explore Northside. Find somewhere quiet.';if(state.day===2)return!f.photo2Done?'Look at the photograph somewhere quiet.':!f.parent2Done?'Go home and decide if you want to talk.':'Find a safe place to spend the afternoon.';if(state.day===3)return!f.friend3Done?'Walk to the park. Sam is there after school.':!f.home3Done?'Go home. Mom wants to try again.':!f.finish?'Find a quiet place, then choose what comes next.':'The week is yours. You can explore or begin again.';return'Explore, talk, and decide what kind of support feels possible.'}
function update(){const p=places[state.location]||places.home;$('locationLabel').textContent=p.name;$('weatherLabel').textContent=p.weather;$('dayLabel').textContent='DAY '+state.day;$('timeLabel').textContent=state.time;$('profileName').textContent=state.name;$('avatarInitial').textContent=state.name.charAt(0).toUpperCase();$('steadyValue').textContent=state.steady;$('energyValue').textContent=state.energy;$('steadyBar').style.width=state.steady+'%';$('energyBar').style.width=state.energy+'%';$('fragmentCount').textContent=Array.from({length:6},(_,i)=>state.fragments.length>i?'●':'○').join(' ');$('objectiveTitle').textContent=state.day===1?'A quiet morning':state.day===2?'A name in the margin':state.day===3?'The missing pieces':'A place to begin';$('objectiveText').textContent=objective();$('threadText').textContent=state.day===1?'A strange photograph has appeared in your backpack.':state.day===2?'Someone knows the name written on the photograph.':'You do not have to remember everything at once.';mapRender()}
function scene(id){const s=scenes[id];modal('dialogueModal');$('speakerLabel').textContent=s.speaker;$('dialogueTitle').textContent=s.title;$('dialogueText').textContent=state.soft?s.text.replace(/self-harm|dysphoria/gi,'difficult feelings'):s.text;$('sceneTag').classList.toggle('hidden',!s.choices.some(c=>c[1].fragment));const list=$('choiceList');list.innerHTML='';s.choices.forEach(([label,e])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{for(const k of ['steady','energy'])if(e[k])state[k]=Math.max(0,Math.min(100,state[k]+e[k]));for(const k of ['truth','trust','agency'])if(e[k])state[k]+=e[k];if(e.fragment&&!state.fragments.includes(e.fragment))state.fragments.push(e.fragment);if(e.note)state.notes.unshift({day:state.day,text:e.note});modal('dialogueModal',false);if(s.after==='finish'){state.flags.finish=true;update();ending();return}state.flags[s.after]=true;update();save()};list.appendChild(b)})}
function ending(){let title,text,symbol;if(state.trust>=7&&state.steady>=35){title='A little more room';text='You have not solved the past, or made every hard day disappear. But you have someone to sit with you, a way to ask for help, and permission to go slowly. That is not a small ending. It is a beginning with room in it.';symbol='✳'}else if(state.truth>=7&&state.agency>=5){title='The words are yours';text='The memories are still incomplete. You have chosen your own words, your own pace, and a boundary you can keep. You do not need perfect understanding to begin caring for yourself.';symbol='◌'}else if(state.steady<24){title='A difficult week';text='By Friday, everything still feels heavy. You do not have to turn that into a lesson. Even here, you are not a failure. The story leaves you at a doorway: a school counselor, a trusted adult, or a helpline can be a next step when you are ready.';symbol='☾'}else{title='One step, then another';text='There are still questions, and not everyone knew how to listen. But the week did not erase you. You can ask one safe person to stay nearby. Nothing has to be decided all at once.';symbol='↗'}$('endingTitle').textContent=title;$('endingText').textContent=text;$('endingSymbol').textContent=symbol;$('endingDetails').textContent=`${state.fragments.length} memory fragments found · ${state.notes.length} moments journaled · Your identity and the ending are yours.`;state.ending=title;modal('endingModal');save()}
function options(){let a=[],f=state.flags,l=state.location,add=(label,fn,x=0,z=5)=>a.push({label,fn,x,z});if(l==='home'){if(state.day===1&&!f.mom1done)add('Talk with Mom',()=>scene('mom1'));if(state.day===1&&f.mom1done&&!f.photoDone)add('Look in your backpack',()=>scene('photo'),-2,4);if(state.day===2&&f.photo2Done&&!f.parent2Done)add('Talk with Dad',()=>scene('parent2'));if(state.day===3&&f.friend3Done&&!f.home3Done)add('Talk with Mom',()=>scene('home3'))}if(l==='school'&&state.day===1){if(f.photoDone&&!f.bullyDone)add('Get through the hallway',()=>scene('bully'));else if(f.bullyDone&&!f.counselorDone)add('Visit Ms. Rivera',()=>scene('counselor'),-2);else if(f.counselorDone&&!f.samDone)add('Talk with Sam',()=>scene('sam'),2)}if(l==='library'&&state.day===2&&!f.photo2Done)add('Read the photograph',()=>scene('photo2'));if(l==='park'&&state.day===3&&!f.friend3Done)add('Meet Sam',()=>scene('friend3'));if(state.day>=3&&f.home3Done&&!f.finish&&['park','library','center'].includes(l))add('Find a quiet place',()=>scene('final'));(places[l].links||[]).forEach(([name,id],i)=>add('Go to '+name,()=>travel(id),i? -2:2,11));let best=null,d=2.2;a.forEach(o=>{let n=Math.hypot(o.x-state.x,o.z-state.z);if(n<d){best=o;d=n}});return best}
function travel(id){state.location=id;state.x=0;state.z=0;state.energy=Math.max(0,state.energy-2);state.time=id==='school'?'MORNING':id==='home'?'EVENING':'AFTERNOON';if(id==='home'&&state.day===1&&state.flags.samDone){advance();return}if(id==='home'&&state.day===2&&state.flags.parent2Done){advance();return}toast('You made it to '+places[id].name.toLowerCase()+'.');update();draw();save()}
function advance(){if(state.day===1){state.day=2;state.time='TUESDAY · AFTER SCHOOL';state.location='home';state.energy=Math.max(25,state.energy-11);state.steady=Math.max(10,state.steady-4);state.flags.bullyDone=true}else if(state.day===2){state.day=3;state.time='WEDNESDAY · AFTER SCHOOL';state.location='park';state.energy=Math.max(18,state.energy-8)}else{state.day=4;state.time='FRIDAY · LATE AFTERNOON';state.location='center';state.energy=Math.max(15,state.energy-6)}update();draw();save()}
function draw(){const c=$('world'),x=c.getContext('2d'),w=c.width,h=c.height,p=places[state.location]||places.home;x.clearRect(0,0,w,h);let sky=x.createLinearGradient(0,0,0,h*.66);sky.addColorStop(0,p.sky);sky.addColorStop(1,'#c1c4b2');x.fillStyle=sky;x.fillRect(0,0,w,h*.66);x.fillStyle=p.wall;x.fillRect(0,h*.3,w,h*.4);x.fillStyle=p.floor;x.beginPath();x.moveTo(0,h*.69);x.lineTo(w,h*.69);x.lineTo(w,h);x.lineTo(0,h);x.fill();x.strokeStyle='#e3d8bd35';x.lineWidth=2;for(let i=-5;i<=5;i++){x.beginPath();x.moveTo(w/2+i*14,h*.69);x.lineTo(w/2+i*85,h);x.stroke()}for(let j=1;j<5;j++){let y=h*.69+h*.31*j*j/25;x.beginPath();x.moveTo(0,y);x.lineTo(w,y);x.stroke()}x.fillStyle='#45524d';x.fillRect(0,h*.29,w,12);x.fillStyle=p.accent;x.fillRect(0,h*.3,w,6);p.objects.forEach((o,i)=>objectDraw(x,o,state.x,state.z,state.yaw,p,i));if(['home','school','shop'].includes(state.location)){x.strokeStyle='#e5eee844';for(let i=0;i<60;i++){let xx=(i*137+Date.now()/28)%w,y=(i*91+Date.now()/16)%h*.72;x.beginPath();x.moveTo(xx,y);x.lineTo(xx-3,y+11);x.stroke()}}let v=x.createRadialGradient(w/2,h*.45,h*.1,w/2,h*.5,h*.75);v.addColorStop(0,'transparent');v.addColorStop(1,'#14231e30');x.fillStyle=v;x.fillRect(0,0,w,h);let n=options(),hint=$('interactionHint');hint.classList.toggle('hidden',!n);if(n)hint.querySelector('span').textContent=n.label}
function objectDraw(x,o,px,pz,yaw,p,i){let [type,ox,z]=o,w=x.canvas.width,h=x.canvas.height,s=1/(z*.13+.35),sx=w/2+(ox-px)*100/(z*.42+1)-yaw*1.1,base=h*.69+(pz-z)*2;x.save();x.translate(sx,base);x.scale(s,s);if(type==='window'){x.fillStyle='#30433e';x.fillRect(-45,-170,90,170);x.fillStyle=p.sky;x.fillRect(-37,-162,74,154);x.fillStyle='#d5cfad';x.fillRect(-3,-162,6,154);x.fillRect(-37,-82,74,5);x.fillStyle='#f0d7a866';x.beginPath();x.arc(-14,-126,14,0,7);x.fill()}else if(type==='table'||type==='desk'||type==='counter'){x.fillStyle='#665646';x.fillRect(-85,-46,170,17);x.fillStyle='#564b3e';x.fillRect(-70,-29,12,65);x.fillRect(58,-29,12,65);x.fillStyle='#ded1aa';x.fillRect(-25,-60,48,13)}else if(type==='plant'||type==='tree'){let t=type==='tree'?1.5:1;x.fillStyle='#475c4a';x.fillRect(-5,-52*t,10,52*t);x.fillStyle=i%2?'#627c5d':'#73896a';for(let a=0;a<5;a++){x.beginPath();x.arc((a-2)*15,-75*t-(a%2)*12,22*t,0,7);x.fill()}x.fillStyle='#765b45';x.fillRect(-20,0,40,12)}else if(type==='bench'){x.fillStyle='#6e6857';x.fillRect(-70,-45,140,12);x.fillRect(-65,-64,130,9);x.fillRect(-55,-33,9,38);x.fillRect(47,-33,9,38)}else if(type==='shelf'||type==='lockers'){x.fillStyle=type==='shelf'?'#625b49':'#526565';x.fillRect(-75,-160,150,160);for(let n=0;n<4;n++){x.fillStyle=type==='shelf'?'#a4936d':'#748783';x.fillRect(-70,-145+n*38,140,4);for(let j=0;j<4;j++){x.fillStyle=['#7b8166','#bc9568','#7d8981','#a97964'][(j+n)%4];x.fillRect(-61+j*33,-177+n*38,24,31)}}}else if(type==='poster'){x.fillStyle='#eee8d4';x.fillRect(-47,-92,94,92);x.fillStyle='#789885';x.fillRect(-35,-78,70,42);x.fillStyle='#b17b62';x.fillRect(-32,-22,64,5)}else if(type==='sofa'){x.fillStyle='#657f70';x.fillRect(-80,-64,160,63);x.fillRect(-93,-52,18,53);x.fillRect(75,-52,18,53);x.fillStyle='#b0b99a';x.fillRect(-55,-53,48,24);x.fillRect(10,-53,48,24)}x.restore()}

function mapRender(){let box=$('mapGrid');box.innerHTML='';[['home','Home'],['school','Northside High'],['shop','Corner shop'],['park','Willow Park'],['library','Public library'],['center','Youth centre']].forEach(([id,name])=>{let d=document.createElement('div');d.className='map-place'+(state.location===id?' current':'');d.innerHTML=`<strong>${name}</strong><span>${id===state.location?'YOU ARE HERE':'OPEN TO EXPLORE'}</span>`;box.appendChild(d)})}
function journal(tab=activeTab){activeTab=tab;document.querySelectorAll('.journal-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let c=$('journalContent'),labels={blueDoor:'A yellow raincoat and a blue door',yellowThread:'The color of a thread from a childhood sweater',mira:'A name on the back of a photograph',rain:'The feeling of rain and a familiar doorstep'};if(tab==='notes')c.innerHTML=state.notes.length?state.notes.map(n=>`<div class="journal-entry"><small>DAY ${n.day}</small>${esc(n.text)}</div>`).join(''):'<p>Nothing written yet. Your moments will appear here as you go.</p>';else if(tab==='memories')c.innerHTML=state.fragments.length?state.fragments.map(f=>`<div class="journal-entry"><small>FRAGMENT · NOT A COMPLETE MEMORY</small>${esc(labels[f]||'A feeling that has not found its words yet.')}</div>`).join(''):'<p>No fragments found yet. You never have to search for them.</p>';else c.innerHTML='<div class="journal-entry"><small>HOME</small>Mom and Dad care about you, but do not always understand.</div><div class="journal-entry"><small>SCHOOL</small>Ms. Rivera is a counselor. Sam offered to walk with you.</div><div class="journal-entry"><small>YOU</small>Your identity is yours to define, change, or leave unanswered.</div>';modal('journalModal')}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function move(dt){let q=dt*.008;if(keys.KeyW||keys.ArrowUp)state.z+=q;if(keys.KeyS||keys.ArrowDown)state.z-=q;if(keys.KeyA)state.x-=q;if(keys.KeyD)state.x+=q;if(keys.ArrowLeft)state.yaw=Math.max(-120,state.yaw-1.6);if(keys.ArrowRight)state.yaw=Math.min(120,state.yaw+1.6);state.x=Math.max(-3.3,Math.min(3.3,state.x));state.z=Math.max(-1,Math.min(10,state.z))}function frame(t){if(!raf)return;move(Math.min(40,t-last||16));last=t;draw();raf=requestAnimationFrame(frame)}
function breathe(){let out=$('breathingStatus'),btn=$('breathingBtn'),i=0,words=['Breathe in gently…','Pause, if that feels okay…','Let the breath go…'];btn.disabled=true;function tick(){if(i>=6){out.textContent='You can return whenever you feel ready.';btn.disabled=false;return}out.textContent=words[i++%3];setTimeout(tick,5000)}tick()}
function setup(){let saved=load();if(saved)$('continueBtn').classList.remove('hidden');$('beginBtn').onclick=()=>show('setupScreen');$('backBtn').onclick=()=>show('titleScreen');$('startGameBtn').onclick=()=>{start(true);save();scene('mom1')};$('continueBtn').onclick=()=>{Object.assign(state,fresh(),load());start(false)};$('journalBtn').onclick=()=>journal();$('pauseBtn').onclick=$('settingsBtn').onclick=()=>modal('settingsModal');$('supportBtn').onclick=()=>modal('supportModal');$('settingsSupport').onclick=()=>{modal('settingsModal',false);modal('supportModal')};$('mapBtn').onclick=()=>modal('mapModal');$('saveBtn').onclick=save;$('resetBtn').onclick=()=>{if(confirm('Erase your saved story and return to the beginning?')){localStorage.removeItem('quietHoursSave');location.reload()}};$('restartEnding').onclick=()=>{localStorage.removeItem('quietHoursSave');location.reload()};$('endingClose').onclick=()=>modal('endingModal',false);$('breathingBtn').onclick=breathe;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal(b.dataset.close,false));document.querySelectorAll('.journal-tabs button').forEach(b=>b.onclick=()=>journal(b.dataset.tab));$('softModeLive').onchange=e=>{state.soft=e.target.checked;$('softMode').checked=state.soft;save()};$('softMode').onchange=e=>state.soft=e.target.checked;document.querySelectorAll('.mobile-controls button').forEach(b=>{let m={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];b.onpointerdown=e=>{e.preventDefault();keys[m]=true};b.onpointerup=b.onpointerleave=()=>keys[m]=false});document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){let opened=[...document.querySelectorAll('.modal')].find(m=>!m.classList.contains('hidden'));if(opened)opened.classList.add('hidden');else modal('settingsModal');return}if(e.key.toLowerCase()==='e'){let n=options();if(n)n.fn();return}if(e.key.toLowerCase()==='j'){journal();return}keys[e.code]=true});document.addEventListener('keyup',e=>keys[e.code]=false);document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m&&m.id!=='endingModal')m.classList.add('hidden')}))}
setup();raf=1;frame(0);
})();

