(() => {
'use strict';
const $ = id => document.getElementById(id);
const STORAGE = 'quietHoursSave';
const placeNames = {home:'Home',school:'Northside High',shop:'Corner shop',park:'Willow Park',library:'Public library',center:'Youth centre'};
const placeDetails = {
  home:{label:'HOME · KITCHEN',sky:'#aab9b5',wall:'#d9d3c3',floor:'#806b5a',accent:'#638a7c',object:'window'},
  school:{label:'NORTHSIDE HIGH · HALL',sky:'#aeb9b6',wall:'#d5d9d3',floor:'#71817d',accent:'#b17860',object:'lockers'},
  shop:{label:'CORNER SHOP',sky:'#d9c8a9',wall:'#e3dbc9',floor:'#8e8067',accent:'#ce9360',object:'shelves'},
  park:{label:'WILLOW PARK',sky:'#a8beb7',wall:'#829c84',floor:'#536f5d',accent:'#d0b77c',object:'tree'},
  library:{label:'PUBLIC LIBRARY',sky:'#b7c5c0',wall:'#d9d6c9',floor:'#897966',accent:'#6a8478',object:'shelves'},
  center:{label:'YOUTH CENTRE',sky:'#b6c8c0',wall:'#ded9ca',floor:'#897d6b',accent:'#b8755f',object:'sofa'}
};
const state = fresh();
function fresh(){return {name:'Alex',gender:'nonbinary',sexuality:'skip',pronouns:'they',trans:'no',soft:false,day:1,step:0,location:'home',x:0,z:0,yaw:0,steady:54,energy:62,notes:[],fragments:[],visited:[],flags:{},ending:null};}
const story = [
 {day:1,loc:'home',time:'BEFORE SCHOOL',speaker:'MOM',title:'A quiet morning',objective:'Check in with Mom before you leave.',text:'Rain threads down the kitchen window. Mom has made toast and left it under a tea towel. Dad is already out. On the table, beside your school bag, is a photograph you do not remember taking: a yellow raincoat, a blue front door, and a child turned away from the camera.',options:[['Ask where the photograph came from.','mom_photo'],['Say you slept badly, but you are okay.','mom_sleep'],['Put the photograph away for now.','mom_leave']]},
 {day:1,loc:'school',time:'FIRST PERIOD',speaker:'SAM',title:'The hallway',objective:'Find Sam near the lockers.',text:'The hallway smells like wet coats and pencil shavings. Sam spots you by the lockers and falls into step. “You vanished at lunch yesterday. No pressure to explain. Want company?” A laugh rises from somewhere behind you, then dissolves into the bell.',options:[['Tell Sam the photo is bothering you.','sam_photo'],['Ask about their weekend instead.','sam_smalltalk'],['Say you would rather walk alone.','sam_alone']]},
 {day:1,loc:'school',time:'LUNCH',speaker:'MS. RIVERA',title:'A door left open',objective:'Visit the counseling office.',text:'Ms. Rivera keeps a jar of peppermint tea bags on her desk. She notices you looking at the closed door. “You can talk, sit quietly, or come back another day. Those are all real choices.” The photograph feels heavy in your pocket.',options:[['Show her the photograph.','counsel_photo'],['Ask what stays private.','counsel_private'],['Take a quiet minute, then leave.','counsel_leave']]},
 {day:1,loc:'home',time:'EVENING',speaker:'DAD',title:'The space between words',objective:'Talk with Dad after dinner.',text:'Dinner is mostly the clink of forks. Dad asks about school; Mom asks if you are eating enough. When you mention the photograph, Dad frowns—not at you, you think, but at the years he cannot account for. “Maybe it came from Grandma’s boxes.”',options:[['Ask him to look through the boxes with you.','dad_boxes'],['Tell them you need less questioning tonight.','dad_space'],['Change the subject to something ordinary.','dad_change']]},
 {day:2,loc:'home',time:'EARLY MORNING',speaker:'YOU',title:'A dream with no ending',objective:'Make a little room before school.',text:'You wake with the blue door from the photograph in your mind. The memory is not a movie; it is a color, a damp sleeve, the sense that someone was calling from another room. You do not have to force it to become more.',options:[['Write down only what you know.','memory_write'],['Ground yourself in the room.','memory_ground'],['Let the fragment pass without following it.','memory_pass']]},
 {day:2,loc:'school',time:'BETWEEN CLASSES',speaker:'SAM',title:'A name on a page',objective:'Meet Sam by the art-room windows.',text:'Sam has found the back of the photograph tucked into your bag. A name is written there in faded blue ink: “Mira.” Sam turns it over carefully. “Could be someone from your family. Could be someone you knew. We can wonder without deciding.”',options:[['Ask Sam to help you look for clues.','mira_clues'],['Say the name feels familiar.','mira_familiar'],['Put it away and focus on today.','mira_today']]},
 {day:2,loc:'library',time:'AFTER SCHOOL',speaker:'LIBRARIAN',title:'The local archive',objective:'Look for a clue at the library.',text:'The librarian remembers a box of neighborhood photographs donated years ago. Together you find a school fair, a paper moon, and a row of children in raincoats. One child has a yellow sleeve and a bright thread at the cuff. No names. No answers, only a possible thread.',options:[['Save the image in your journal.','archive_save'],['Ask about the neighborhood instead.','archive_neighborhood'],['Stop searching for today.','archive_stop']]},
 {day:2,loc:'home',time:'LATE EVENING',speaker:'MOM',title:'A difficult sentence',objective:'Tell Mom what you need her to understand.',text:'Mom finds you at the kitchen table, turning the photograph over and over. She starts to say that everyone has hard days. Then she stops herself. “I want to understand. I might get it wrong. Could you tell me what would help tonight?”',options:[['Ask her to listen without fixing it.','mom_listen'],['Ask her to help contact Ms. Rivera.','mom_help'],['Say you are not ready to talk.','mom_notyet']]},
 {day:3,loc:'park',time:'AFTER SCHOOL',speaker:'YOU',title:'Willow Park',objective:'Take a walk where the trees are quiet.',text:'The rain has thinned to mist. A willow leans over the path, its leaves moving like a curtain. For a moment you remember a yellow raincoat, a hand in yours, the smell of wet leaves. The scene fades before you can see a face. You are here, now, with both feet on the path.',fragment:'yellowThread',options:[['Stay with the present: name five things you see.','park_ground'],['Let the feeling be here without chasing it.','park_feel'],['Call Sam and ask them to meet you.','park_call']]},
 {day:3,loc:'school',time:'AFTER CLASS',speaker:'MS. RIVERA',title:'What the memory can and cannot say',objective:'Check in with Ms. Rivera.',text:'Ms. Rivera listens as you describe the fragment. “A feeling can be real without every detail being clear. Memories can shift, and we should not fill the gaps for you. You deserve support either way.” She offers to help you make a plan for difficult school days.',options:[['Make a plan together.','plan_make'],['Ask how to find a therapist.','plan_therapy'],['Thank her and keep the plan simple.','plan_simple']]},
 {day:3,loc:'school',time:'LATE AFTERNOON',speaker:'CLASSMATE',title:'A careless joke',objective:'Choose how to handle a hurtful comment.',text:'At the lockers, a classmate makes a joke about the way you dress. It lands harder than they seem to expect. Sam is close by; so is a teacher. You do not owe anyone a performance of being fine.',sensitive:true,options:[['Say clearly: “That was not okay.”','bully_boundary'],['Move away and find a safe person.','bully_leave'],['Tell a teacher what happened.','bully_report']]},
 {day:4,loc:'home',time:'MORNING',speaker:'DAD',title:'The box in the closet',objective:'Open Grandma’s box with Dad.',text:'Dad brings down a cardboard box dusted with lint. Inside are recipe cards, a broken wind-up bird, and a knitted sweater with one bright yellow thread at the cuff. He sits on the floor beside you. “I wish I had asked about this sooner.” The photograph still does not tell a complete story.',fragment:'blueDoor',options:[['Ask him to tell you what he remembers.','box_story'],['Tell him you need a break.','box_break'],['Keep the thread and leave the rest for later.','box_thread']]},
 {day:4,loc:'shop',time:'AFTER SCHOOL',speaker:'MR. LEE',title:'The corner shop',objective:'Pick up tea and something small to eat.',text:'Mr. Lee recognizes the photograph from the old neighborhood fair. He remembers a child named Mira who used to trade paper stars for lemon candies. “I don’t know if that is your Mira,” he says. “But I remember the stars.” Outside, the clouds are beginning to lift.',options:[['Ask what the fair was like.','shop_fair'],['Buy a lemon candy and keep the story.','shop_candy'],['Thank him and head out.','shop_leave']]},
 {day:4,loc:'center',time:'EARLY EVENING',speaker:'JULES',title:'A room with soft chairs',objective:'Visit the youth centre.',text:'At the youth centre, Jules is setting out mugs for the after-school group. They tell you the room is open to anyone who needs somewhere quiet. No introductions required. On the noticeboard is a flyer for a weekend art table.',options:[['Stay for the art table.','center_art'],['Ask about one-to-one support.','center_support'],['Sit quietly, then go home.','center_quiet']]},
 {day:5,loc:'home',time:'MORNING',speaker:'YOU',title:'A name in your own handwriting',objective:'Decide what you want to write in your journal.',text:'You write “Mira” on a fresh page. The name might belong to a friend, a cousin, a story you heard, or a memory not ready to settle. The page does not demand an answer. You notice your shoulders have lowered a little.',fragment:'mira',options:[['Write a letter with no need to send it.','letter_write'],['Write questions instead of answers.','letter_questions'],['Close the journal and make breakfast.','letter_close']]},
 {day:5,loc:'school',time:'MIDDAY',speaker:'SAM',title:'Walking beside someone',objective:'Talk with Sam about the week.',text:'Sam asks how the week has been. You tell them it has been more than one thing: tiring, strange, sometimes kind. “I’m glad you let me walk beside you,” they say. You realize support can be ordinary—a seat saved, a message answered, a person who does not rush you.',options:[['Tell Sam what you appreciate.','sam_thanks'],['Ask if they want to hang out this weekend.','sam_weekend'],['Say you need quiet, but not goodbye.','sam_quiet']]},
 {day:5,loc:'center',time:'LATE AFTERNOON',speaker:'JULES',title:'A small plan for tomorrow',objective:'Choose one support to carry forward.',text:'Jules helps you write a small plan: one person you can contact, one place you can go, and one thing that brings you back to the present. It is not a promise to feel better every day. It is a handrail for the next step.',options:[['Choose a trusted adult as your first contact.','future_adult'],['Choose Sam or another friend.','future_friend'],['Choose the youth centre as a place to return.','future_center']]},
 {day:6,loc:'home',time:'EVENING',speaker:'FAMILY',title:'The conversation you choose',objective:'Tell your family what you want them to know.',text:'The family sits together after dinner. Nobody has perfect words. You can decide how much of your inner life to share, and what to keep for yourself. Mom reaches for the tea. Dad waits instead of filling the silence.',options:[['Share what has felt heavy, and what helps.','family_share'],['Ask them to learn alongside you.','family_learn'],['Keep some things private and ask for patience.','family_private']]},
 {day:7,loc:'park',time:'LATE AFTERNOON',speaker:'YOU',title:'The blue door',objective:'Return to Willow Park and decide what comes next.',text:'The week ends under a pale clearing sky. You remember a blue door, maybe the one from the photograph. You remember the bright thread. You remember that a fragment is not a verdict and that you are allowed to keep asking for help. The next page belongs to you.',fragment:'rain',final:true,options:[['Choose a gentler next step.','ending_gentle'],['Choose to keep looking, with support.','ending_search'],['Choose rest and let the questions wait.','ending_rest']]}
];
