function modal(id,on=true){$(id).classList.toggle('hidden',!on);if(on){const b=$(id).querySelector('button');if(b)b.focus()}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));toast('Progress saved on this device.')}catch(e){toast('Could not save in this browser.')}}
