function cleanState(data){const base=fresh();if(!data||typeof data!=='object')return base;for(const k of Object.keys(base))if(data[k]!==undefined)base[k]=data[k];base.step=Math.max(0,Math.min(story.length-1,Number(base.step)||0));base.day=story[base.step].day;base.location=placeDetails[base.location]?base.location:story[base.step].loc;base.x=0;base.z=0;base.yaw=0;base.notes=Array.isArray(base.notes)?base.notes:[];base.fragments=Array.isArray(base.fragments)?base.fragments:[];base.visited=Array.isArray(base.visited)?base.visited:[];base.flags=base.flags&&typeof base.flags==='object'?base.flags:{};return base}
